4		"fmt"
5		"strings"
6	)
7	
8	// CreateDraft 在某次就诊下新建一条诊断或医嘱草稿。
9	// 患者必须存在且未停用；就诊必须属于该患者（否则 ErrMismatchedPatient）；
10	// 类别必须是 Diagnosis 或 Order，内容不能为空。
11	func (s *Store) CreateDraft(actor Actor, patientID, encounterID ID, category, content string) (Record, error) {
12		if !actor.valid() || !actor.IsInternal() {
13			return Record{}, ErrAccessDenied
14		}
15		if patientID == "" || encounterID == "" {
16			return Record{}, fmt.Errorf("%w: patient and encounter ids are required", ErrInvalidArgument)
17		}
18		if !validCategory(category) {
19			return Record{}, fmt.Errorf("%w: category must be %q or %q", ErrInvalidArgument, Diagnosis, Order)
20		}
21		if strings.TrimSpace(content) == "" {
22			return Record{}, fmt.Errorf("%w: draft content is required", ErrInvalidArgument)
23		}
24	
25		var result Record
26		err := s.mutate(func(snap *snapshot) error {
27			if _, err := requireActivePatient(snap, patientID); err != nil {
28				return err
29			}
30			if _, err := requireEncounter(snap, patientID, encounterID); err != nil {
31				return err
32			}
33			r := &Record{
34				ID:           newID("rec"),
35				PatientID:    patientID,
36				EncounterID:  encounterID,
37				Category:     category,
38				DraftContent: content,
39				HasDraft:     true,
40			}
41			snap.Records[r.ID] = r
42			result = *r
43			return nil
44		})
45		return result, err
46	}
47	
48	// UpdateDraft 修改尚未生效的草稿内容。已生效的记录不能再走草稿路径
49	// （返回 ErrActive），必须使用 CorrectRecord 更正。
50	func (s *Store) UpdateDraft(actor Actor, recordID ID, content string) (Record, error) {
51		if !actor.valid() || !actor.IsInternal() {
52			return Record{}, ErrAccessDenied
53		}
54		if strings.TrimSpace(content) == "" {
55			return Record{}, fmt.Errorf("%w: draft content is required", ErrInvalidArgument)
56		}
57	
58		var result Record
59		err := s.mutate(func(snap *snapshot) error {
60			r, err := requireDraftRecord(snap, recordID)
61			if err != nil {
62				return err
63			}
64			if _, err := requireActivePatient(snap, r.PatientID); err != nil {
65				return err
66			}
67			r.DraftContent = content
68			result = *r
69			return nil
70		})
71		return result, err
72	}
73	
74	// DeleteDraft 删除一条尚未生效的草稿及其记录。草稿从未生效，
75	// 因此删除不影响任何生效内容，也不产生审计事件。
76	func (s *Store) DeleteDraft(actor Actor, recordID ID) error {
77		if !actor.valid() || !actor.IsInternal() {
78			return ErrAccessDenied
79		}
80		return s.mutate(func(snap *snapshot) error {
81			r, err := requireDraftRecord(snap, recordID)
82			if err != nil {
83				return err
84			}
85			if _, err := requireActivePatient(snap, r.PatientID); err != nil {
86				return err
87			}
88			delete(snap.Records, r.ID)
89			return nil
90		})
91	}
92	
93	// ActivateRecord 使草稿生效：固化当时的完整内容与时间为第 1 版。
94	// 生效后草稿被清除，记录不能再被直接覆盖或删除，只能更正。
95	// 生效与审计事件在同一次原子落盘中保留。
96	func (s *Store) ActivateRecord(actor Actor, recordID ID) (Version, error) {
97		if !actor.valid() || !actor.IsInternal() {
98			return Version{}, ErrAccessDenied
99		}
100		var result Version
101		err := s.mutate(func(snap *snapshot) error {
102			r, err := requireDraftRecord(snap, recordID)
103			if err != nil {
104				return err
105			}
106			if _, err := requireActivePatient(snap, r.PatientID); err != nil {
107				return err
108			}
109			now := s.now()
110			v := &Version{
111				ID:        newID("ver"),
112				RecordID:  r.ID,
113				Number:    1,
114				Content:   r.DraftContent,
115				Category:  r.Category,
116				CreatedAt: now,
117			}
118			snap.Versions[v.ID] = v
119			r.CurrentVersionID = v.ID
120			r.Versions = append(r.Versions, v.ID)
121			r.HasDraft = false
122			r.DraftContent = ""
123			s.addAudit(snap, r.PatientID, actor, ActionActivated, "record", r.ID, now)
124			result = *v
125			return nil
126		})
127		return result, err
128	}
129	
130	// CorrectRecord 对当前生效版本进行更正，生成同一条记录的新版本。
131	//
132	// reason 必须非空；expectedCurrentVersion 必须等于记录当前版本号，
133	// 否则返回 ErrConflict 且状态保持不变。旧版本内容、版本关系（PrevID）
134	// 与更正原因都会保留。新版本与审计事件一同原子落盘。
135	func (s *Store) CorrectRecord(actor Actor, recordID ID, expectedCurrentVersion int, content, reason string) (Version, error) {
136		if !actor.valid() || !actor.IsInternal() {
137			return Version{}, ErrAccessDenied
138		}
139		if strings.TrimSpace(content) == "" {
140			return Version{}, fmt.Errorf("%w: corrected content is required", ErrInvalidArgument)
141		}
142		if strings.TrimSpace(reason) == "" {
143			return Version{}, fmt.Errorf("%w: correction reason is required", ErrInvalidArgument)
144		}
145		if expectedCurrentVersion <= 0 {
146			return Version{}, fmt.Errorf("%w: expected current version must be positive", ErrInvalidArgument)
147		}
148	
149		var result Version
150		err := s.mutate(func(snap *snapshot) error {
151			r := snap.Records[recordID]
152			if r == nil {
153				return fmt.Errorf("%w: record %q", ErrNotFound, recordID)
154			}
155			if _, err := requireActivePatient(snap, r.PatientID); err != nil {
156				return err
157			}
158			if r.CurrentVersionID == "" {
159				return fmt.Errorf("%w: record %q has no effective version; activate its draft first", ErrInvalidArgument, recordID)
160			}
161			current := snap.Versions[r.CurrentVersionID]
162			if current == nil {
163				// 内部状态不应出现；按不存在处理，拒绝写入。
164				return fmt.Errorf("%w: current version %q", ErrNotFound, r.CurrentVersionID)
165			}
166			if current.Number != expectedCurrentVersion {
167				return fmt.Errorf("%w: record %q is at version %d, not %d",
168					ErrConflict, recordID, current.Number, expectedCurrentVersion)
169			}
170	
171			now := s.now()
172			v := &Version{
173				ID:        newID("ver"),
174				RecordID:  r.ID,
175				Number:    current.Number + 1,
176				Content:   content,
177				Category:  r.Category,
178				CreatedAt: now,
179				PrevID:    current.ID,
180				Reason:    reason,
181			}
182			snap.Versions[v.ID] = v
183			r.CurrentVersionID = v.ID
184			r.Versions = append(r.Versions, v.ID)
185			s.addAudit(snap, r.PatientID, actor, ActionCorrected, "record", r.ID, now)
186			result = *v
187			return nil
188		})
189		return result, err
190	}
191	
192	// requireDraftRecord 取出仍处于草稿阶段（有草稿且尚无生效版本）的记录。
193	func requireDraftRecord(snap *snapshot, recordID ID) (*Record, error) {
194		r := snap.Records[recordID]
195		if r == nil {
196			return nil, fmt.Errorf("%w: record %q", ErrNotFound, recordID)
197		}
198		if r.CurrentVersionID != "" || !r.HasDraft {
199			return nil, fmt.Errorf("%w: record %q is already effective", ErrActive, recordID)
200		}
201		return r, nil
202	}
