46		c := 0
47		_ = s.view(func(snap *snapshot) error { c = len(snap.Records); return nil })
48		return c
49	}
50	
51	func auditActions(events []AuditEvent) map[string]int {
52		m := map[string]int{}
53		for _, e := range events {
54			m[e.Action]++
55		}
56		return m
57	}
